        raise OCRFailure(
            f"ABBYY returned invalid XML: {content[:1000]!r}"
        ) from exc


def submit_pdf(
    pdf_path: Path,
    *,
    application_id: str,
    password: str,
    base_url: str,
    timeout_seconds: int = 1800,
    poll_interval_seconds: float = 4.0,
) -> bytes:
    session = requests.Session()
    session.auth = HTTPBasicAuth(application_id, password)
    session.headers.update({"User-Agent": "kept-contract-text/1.0"})

    process_url = f"{base_url.rstrip('/')}/processDocument"
    parameters = {
        "language": "English",
        "profile": "documentConversion",
        "exportFormat": "xml",
    }

    with pdf_path.open("rb") as pdf:
        response = session.post(
            process_url,
            params=parameters,
            data=pdf,
            headers={"Content-Type": "application/pdf"},
            timeout=(30, 300),
        )

    if not response.ok:
        raise OCRFailure(
            f"ABBYY submission failed ({response.status_code}): "
            f"{response.text[:2000]}"
        )

    task = first_task(parse_xml_response(response.content))
    task_id = case_insensitive_attribute(task, "id")
    if not task_id:
        raise OCRFailure("ABBYY did not return a task ID.")

    deadline = time.monotonic() + timeout_seconds
    status_url = f"{base_url.rstrip('/')}/getTaskStatus"

    while True:
