        if status in TERMINAL_FAILURE_STATES:
            error = (
                case_insensitive_attribute(task, "error")
                or case_insensitive_attribute(task, "description")
                or ET.tostring(task, encoding="unicode")
            )
            raise OCRFailure(f"ABBYY task {task_id} failed: {error}")

