            result_url = (
                case_insensitive_attribute(task, "resultUrl")
                or case_insensitive_attribute(task, "resultUrl2")
            )
            if not result_url:
                raise OCRFailure(
                    f"ABBYY task {task_id} completed without a result URL."
                )

            result = session.get(result_url, timeout=(30, 300))
            if not result.ok:
                raise OCRFailure(
                    f"Could not download ABBYY task {task_id} "
                    f"({result.status_code}): {result.text[:2000]}"
                )
            return unpack_xml_if_needed(result.content)

        time.sleep(poll_interval_seconds)


