    if not content.startswith(b"PK"):
        return content

    with zipfile.ZipFile(io.BytesIO(content)) as archive:
        xml_files = [
            name for name in archive.namelist() if name.lower().endswith(".xml")
        ]
        if not xml_files:
            raise OCRFailure("ABBYY result archive did not contain XML.")
