    Returns (strikeout_attribute_seen, is_struck_out).

    ABBYY versions may use slightly different attribute names or values, so
    this accepts the common variants while still failing closed if no such
    metadata appears anywhere in the result.
    """
    seen = False
    struck = False

    for raw_key, raw_value in element.attrib.items():
        key = local_name(raw_key).replace("-", "").replace("_", "")
        value = raw_value.strip().lower()

        if key in {
            "strikeout",
            "strikethrough",
            "isstruckout",
            "crossedout",
            "deleted",
        }:
            seen = True
            if value not in {"", "0", "false", "no", "none", "normal", "off"}:
                struck = True

        elif key in {"textdecoration", "decoration"}:
            seen = True
            if "line-through" in value or "strik" in value:
                struck = True

    return seen, struck


def parse_confidence(element: ET.Element) -> float | None:
    for candidate in ("charConfidence", "confidence"):
        value = case_insensitive_attribute(element, candidate)
        if value is None:
            continue
        try:
            confidence = float(value)
            return confidence * 100.0 if 0.0 <= confidence <= 1.0 else confidence
        except ValueError:
            pass
    return None


