    node: ET.Element,
    *,
    inherited_strikeout: bool = False,
) -> Iterator[dict[str, Any]]:
    metadata_seen, node_struck = strikeout_state(node)
    struck = inherited_strikeout or node_struck

    if local_name(node.tag) == "charparams":
        text = "".join(node.itertext())
        if text:
            yield {
                "text": text,
                "struck": struck,
                "confidence": parse_confidence(node),
                "strikeout_metadata_seen": metadata_seen,
            }
        return

    for child in node:
        yield from iter_character_tokens(
            child,
            inherited_strikeout=struck,
        )


def group_token_text(
    tokens: list[dict[str, Any]],
    predicate,
) -> list[str]:
    groups: list[str] = []
    current: list[str] = []

    for token in tokens:
        if predicate(token):
            current.append(token["text"])
        elif current:
            groups.append("".join(current))
            current = []

    if current:
        groups.append("".join(current))

    return [group for group in groups if group]


def top_level_blocks(page: ET.Element) -> list[ET.Element]:
    parents = {child: parent for parent in page.iter() for child in parent}

    blocks: list[ET.Element] = []
    for element in page.iter():
        if local_name(element.tag) != "block":
            continue

        parent = parents.get(element)
        nested_in_block = False
        while parent is not None and parent is not page:
            if local_name(parent.tag) == "block":
                nested_in_block = True
                break
            parent = parents.get(parent)

        if not nested_in_block:
            blocks.append(element)

    return blocks


def descendants(element: ET.Element, tag_name: str) -> list[ET.Element]:
    wanted = tag_name.lower()
    return [item for item in element.iter() if local_name(item.tag) == wanted]


