    xml_content: bytes,
    *,
    source_pdf: Path,
    low_confidence_threshold: float = 85.0,
    require_strikeout_metadata: bool = True,
    require_deleted_text: bool = True,
) -> tuple[str, dict[str, Any]]:
    root = parse_xml_response(xml_content)
    pages = descendants(root, "page")

    if not pages:
        raise OCRFailure("ABBYY XML contained no pages.")

    output_pages: list[str] = []
    deleted_spans: list[dict[str, Any]] = []
    low_confidence_spans: list[dict[str, Any]] = []

    character_token_count = 0
    strikeout_metadata_seen = False
    struck_character_count = 0

    def consume_line(
        line: ET.Element,
        *,
        page_number: int,
        location: str,
    ) -> str:
        nonlocal character_token_count
        nonlocal strikeout_metadata_seen
        nonlocal struck_character_count

        tokens = list(iter_character_tokens(line))
        character_token_count += len(tokens)
        strikeout_metadata_seen |= any(
            token["strikeout_metadata_seen"] for token in tokens
        )
        struck_character_count += sum(
            len(token["text"]) for token in tokens if token["struck"]
        )

        kept = "".join(
            token["text"] for token in tokens if not token["struck"]
        ).strip()

        for removed in group_token_text(tokens, lambda token: token["struck"]):
            if removed.strip():
                deleted_spans.append(
                    {
                        "page": page_number,
                        "location": location,
                        "deleted_text": removed,
                        "kept_line": kept,
                    }
                )

        low_confidence = group_token_text(
            tokens,
            lambda token: (
                not token["struck"]
                and token["confidence"] is not None
                and token["confidence"] < low_confidence_threshold
            ),
        )
        for uncertain in low_confidence:
            if uncertain.strip():
                low_confidence_spans.append(
                    {
                        "page": page_number,
                        "location": location,
                        "text": uncertain,
                        "kept_line": kept,
                    }
                )

        return kept

    for page_number, page in enumerate(pages, start=1):
        page_lines: list[str] = []
        blocks = top_level_blocks(page)

        if not blocks:
            blocks = [page]

        for block_number, block in enumerate(blocks, start=1):
            block_type = (
                case_insensitive_attribute(block, "blockType") or ""
            ).lower()

            if block_type == "table":
                rows = descendants(block, "row")
                for row_number, row in enumerate(rows, start=1):
                    cells = [
                        child
                        for child in row
                        if local_name(child.tag) == "cell"
                    ]
                    if not cells:
                        cells = descendants(row, "cell")

                    rendered_cells: list[str] = []
                    for cell_number, cell in enumerate(cells, start=1):
                        rendered_lines: list[str] = []
                        for line_number, line in enumerate(
                            descendants(cell, "line"), start=1
                        ):
                            text = consume_line(
                                line,
                                page_number=page_number,
                                location=(
                                    f"table {block_number}, row {row_number}, "
                                    f"cell {cell_number}, line {line_number}"
                                ),
                            )
                            if text:
                                rendered_lines.append(text)

                        rendered_cells.append(" / ".join(rendered_lines))

                    if any(rendered_cells):
                        page_lines.append("\t".join(rendered_cells))
            else:
                for line_number, line in enumerate(
                    descendants(block, "line"), start=1
                ):
                    text = consume_line(
                        line,
                        page_number=page_number,
                        location=f"block {block_number}, line {line_number}",
                    )
                    if text:
                        page_lines.append(text)

        output_pages.append(
            f"[PAGE {page_number}]\n" + "\n".join(page_lines)
        )

    if character_token_count == 0:
        raise ReviewRequired(
            "ABBYY returned no character-level OCR tokens; do not send this "
            "document to the answering agent."
        )

    if require_strikeout_metadata and not strikeout_metadata_seen:
        raise ReviewRequired(
            "The ABBYY result contained no strikeout metadata. Plain OCR text "
            "cannot safely distinguish retained wording from deletions."
        )

    if require_deleted_text and struck_character_count == 0:
        raise ReviewRequired(
            "No crossed-out characters were detected in this negotiated "
            "document. Route it to manual review or rerun with "
            "--allow-no-deletions only after confirming the scan has none."
        )

    audit = {
        "source_file": source_pdf.name,
        "source_sha256": hashlib.sha256(source_pdf.read_bytes()).hexdigest(),
        "api": "ABBYY Cloud OCR SDK",
        "export_format": "FineReader XML",
        "page_count": len(pages),
        "character_token_count": character_token_count,
        "strikeout_metadata_seen": strikeout_metadata_seen,
        "struck_character_count": struck_character_count,
        "deleted_spans": deleted_spans,
        "low_confidence_threshold": low_confidence_threshold,
        "low_confidence_retained_spans": low_confidence_spans,
        "manual_review_recommended": bool(low_confidence_spans),
    }

    return "\n\n".join(output_pages).rstrip() + "\n", audit


def atomic_write(path: Path, content: str) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    temporary = path.with_name(f".{path.name}.tmp")
    temporary.write_text(content, encoding="utf-8")
    temporary.replace(path)


def main() -> int:
    parser = argparse.ArgumentParser(
        description="Extract only non-struck wording from a scanned contract."
    )
    parser.add_argument("pdf", type=Path)
    parser.add_argument("--output", type=Path, required=True)
    parser.add_argument("--audit", type=Path, required=True)
    parser.add_argument("--low-confidence-threshold", type=float, default=85.0)
    parser.add_argument(
        "--allow-no-deletions",
        action="store_true",
        help="Do not fail when ABBYY detects no crossed-out text.",
    )
    parser.add_argument(
        "--allow-missing-strikeout-metadata",
        action="store_true",
        help="Unsafe: permit XML that exposes no strikeout metadata.",
    )
    args = parser.parse_args()

    if not args.pdf.is_file():
        parser.error(f"PDF not found: {args.pdf}")

    application_id = os.environ.get("ABBYY_APPLICATION_ID")
    password = os.environ.get("ABBYY_PASSWORD")
    base_url = os.environ.get("ABBYY_CLOUD_URL", DEFAULT_ABBYY_URL)

    if not application_id or not password:
        parser.error(
            "Set ABBYY_APPLICATION_ID and ABBYY_PASSWORD."
        )

    try:
        xml_content = submit_pdf(
            args.pdf,
            application_id=application_id,
            password=password,
            base_url=base_url,
        )
        kept_text, audit = extract_kept_text(
            xml_content,
            source_pdf=args.pdf,
            low_confidence_threshold=args.low_confidence_threshold,
            require_strikeout_metadata=(
                not args.allow_missing_strikeout_metadata
            ),
            require_deleted_text=not args.allow_no_deletions,
        )
        atomic_write(args.output, kept_text)
        atomic_write(
            args.audit,
            json.dumps(audit, indent=2, ensure_ascii=False) + "\n",
        )
    except (OCRFailure, ReviewRequired) as exc:
        print(f"REVIEW REQUIRED: {exc}", file=sys.stderr)
        return 2

    print(
        json.dumps(
            {
                "status": "completed",
                "kept_text": str(args.output),
                "audit": str(args.audit),
                "manual_review_recommended": audit[
                    "manual_review_recommended"
                ],
            },
            indent=2,
        )
    )
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
