    ranges: list[tuple[int, int]] = []

    for segment in text_anchor.text_segments:
        start = int(segment.start_index or 0) - base
        end = int(segment.end_index or 0) - base

        start = max(0, min(start, text_length))
        end = max(0, min(end, text_length))

        if end > start:
            ranges.append((start, end))

    return ranges


def merge_ranges(ranges: Iterable[tuple[int, int]]) -> list[tuple[int, int]]:
    ordered = sorted(ranges)
    if not ordered:
        return []

    merged = [ordered[0]]
    for start, end in ordered[1:]:
        previous_start, previous_end = merged[-1]
        if start <= previous_end:
            merged[-1] = (previous_start, max(previous_end, end))
        else:
            merged.append((start, end))

    return merged


def remove_ranges_from_slice(
    text: str,
    slice_start: int,
    slice_end: int,
    removed_ranges: list[tuple[int, int]],
) -> str:
    parts: list[str] = []
    cursor = slice_start

    for removed_start, removed_end in removed_ranges:
        if removed_end <= slice_start:
            continue
        if removed_start >= slice_end:
            break

        start = max(slice_start, removed_start)
        end = min(slice_end, removed_end)

        if start > cursor:
            parts.append(text[cursor:start])
        cursor = max(cursor, end)

    if cursor < slice_end:
        parts.append(text[cursor:slice_end])

    return "".join(parts)


def clean_extracted_text(text: str) -> str:
    # Collapse whitespace left behind by deleted words without destroying lines.
    text = text.replace("\r\n", "\n").replace("\r", "\n")
    text = re.sub(r"[ \t]+", " ", text)
    text = re.sub(r" *\n *", "\n", text)
    text = re.sub(r"\n{3,}", "\n\n", text)
    return text.strip()


def extract_document_pages(
    doc: documentai.Document,
    stats: ExtractionStats,
) -> list[str]:
    source_text = doc.text or ""
    anchor_base = document_anchor_base(doc)
    struck_ranges: list[tuple[int, int]] = []

    for page in doc.pages:
        for token in page.tokens:
            stats.total_tokens += 1

            if has_message_field(token, "style_info"):
                stats.tokens_with_style_metadata += 1

            if bool(token.style_info.strikeout):
                stats.struck_tokens += 1
                token_ranges = anchor_ranges(
                    token.layout.text_anchor,
                    len(source_text),
                    anchor_base,
                )
                struck_ranges.extend(token_ranges)
                stats.struck_characters += sum(end - start for start, end in token_ranges)

    struck_ranges = merge_ranges(struck_ranges)
    extracted_pages: list[str] = []

    for page in doc.pages:
        stats.pages += 1
        page_ranges = anchor_ranges(
            page.layout.text_anchor,
            len(source_text),
            anchor_base,
        )

        # Fallback for processor outputs that do not populate Page.layout.
        if not page_ranges:
            token_ranges = [
                text_range
                for token in page.tokens
                for text_range in anchor_ranges(
                    token.layout.text_anchor,
                    len(source_text),
                    anchor_base,
                )
            ]
            if token_ranges:
                page_ranges = [
                    (
                        min(start for start, _ in token_ranges),
                        max(end for _, end in token_ranges),
                    )
                ]

        page_parts = [
            remove_ranges_from_slice(source_text, start, end, struck_ranges)
            for start, end in page_ranges
        ]
        extracted_pages.append(clean_extracted_text("\n".join(page_parts)))

    # Defensive fallback if pages were unexpectedly omitted.
    if not doc.pages and source_text:
        stats.pages += 1
        extracted_pages.append(
            clean_extracted_text(
                remove_ranges_from_slice(
                    source_text,
                    0,
                    len(source_text),
                    struck_ranges,
                )
            )
        )

    return extracted_pages


def make_process_options() -> documentai.ProcessOptions:
    return documentai.ProcessOptions(
        ocr_config=documentai.OcrConfig(
            # Uses the embedded text in born-digital PDFs while Document AI
            # still computes visual/font style information.
            enable_native_pdf_parsing=True,
            # Encourages finer tokenization for edits within words or numbers.
            enable_symbol=True,
            premium_features=documentai.OcrConfig.PremiumFeatures(
                compute_style_info=True,
            ),
        )
    )


def process_pdf(
    pdf_path: Path,
    project_id: str,
    location: str,
    processor_id: str,
    processor_version: str | None,
    bucket_name: str,
    keep_gcs_artifacts: bool,
) -> tuple[str, ExtractionStats]:
    if not pdf_path.is_file():
        raise FileNotFoundError(pdf_path)
    if pdf_path.suffix.lower() != ".pdf":
        raise ValueError("Input must be a PDF")

    api_endpoint = f"{location}-documentai.googleapis.com"
    docai_client = documentai.DocumentProcessorServiceClient(
        client_options={"api_endpoint": api_endpoint}
    )
    storage_client = storage.Client(project=project_id)
    bucket = storage_client.bucket(bucket_name)

    job_id = uuid.uuid4().hex
    input_key = f"contract-extraction/input/{job_id}/{pdf_path.name}"
    output_prefix = f"contract-extraction/output/{job_id}/"
    input_uri = f"gs://{bucket_name}/{input_key}"
    output_uri = f"gs://{bucket_name}/{output_prefix}"

    if processor_version:
        processor_name = docai_client.processor_version_path(
            project_id,
            location,
            processor_id,
            processor_version,
        )
    else:
        processor_name = docai_client.processor_path(
            project_id,
            location,
            processor_id,
        )

    input_blob = bucket.blob(input_key)

    try:
        input_blob.upload_from_filename(
            str(pdf_path),
            content_type="application/pdf",
        )

        request = documentai.BatchProcessRequest(
            name=processor_name,
            input_documents=documentai.BatchDocumentsInputConfig(
                gcs_documents=documentai.GcsDocuments(
                    documents=[
                        documentai.GcsDocument(
                            gcs_uri=input_uri,
                            mime_type="application/pdf",
                        )
                    ]
                )
            ),
            document_output_config=documentai.DocumentOutputConfig(
                gcs_output_config=documentai.DocumentOutputConfig.GcsOutputConfig(
                    gcs_uri=output_uri,
                )
            ),
            process_options=make_process_options(),
            skip_human_review=True,
        )

        operation = docai_client.batch_process_documents(request=request)
        operation.result(timeout=7200)

        output_blobs = sorted(
            (
                blob
                for blob in storage_client.list_blobs(
                    bucket_name,
                    prefix=output_prefix,
                )
                if blob.name.endswith(".json")
            ),
            key=lambda blob: blob.name,
        )

        if not output_blobs:
            raise RuntimeError("Document AI completed without producing JSON output")

        documents: list[tuple[int, str, documentai.Document]] = []
        for blob in output_blobs:
            document = documentai.Document.from_json(blob.download_as_text())
            shard_index = int(getattr(document.shard_info, "shard_index", 0) or 0)
            documents.append((shard_index, blob.name, document))

        documents.sort(key=lambda item: (item[0], item[1]))

        stats = ExtractionStats()
        page_texts: list[str] = []

        for _, _, document in documents:
            page_texts.extend(extract_document_pages(document, stats))

        numbered_pages = [
            f"[Page {page_number}]\n{page_text}".rstrip()
            for page_number, page_text in enumerate(page_texts, start=1)
        ]
        return "\n\n".join(numbered_pages).strip() + "\n", stats

    finally:
        if not keep_gcs_artifacts:
            try:
                input_blob.delete()
            except Exception:
                pass

            try:
                for blob in storage_client.list_blobs(
                    bucket_name,
                    prefix=output_prefix,
                ):
                    blob.delete()
            except Exception:
                pass


def main() -> int:
    parser = argparse.ArgumentParser(
        description="Remove struck-out contract language using Google Document AI."
    )
    parser.add_argument("input_pdf", type=Path)
    parser.add_argument("output_text", type=Path)
    parser.add_argument(
        "--allow-no-strikeout",
        action="store_true",
        help="Allow successful output when no struck-out tokens are detected.",
    )
    parser.add_argument(
        "--keep-gcs-artifacts",
        action="store_true",
        help="Do not delete the uploaded PDF and Document AI output.",
    )
    args = parser.parse_args()

    project_id = require_env("GOOGLE_CLOUD_PROJECT")
    location = require_env("GOOGLE_CLOUD_LOCATION")
    processor_id = require_env("DOCUMENT_AI_PROCESSOR_ID")
    processor_version = os.environ.get("DOCUMENT_AI_PROCESSOR_VERSION")
    bucket_name = require_env("GCS_BUCKET")

    extracted_text, stats = process_pdf(
        pdf_path=args.input_pdf,
        project_id=project_id,
        location=location,
        processor_id=processor_id,
        processor_version=processor_version,
        bucket_name=bucket_name,
        keep_gcs_artifacts=args.keep_gcs_artifacts,
    )

    if stats.total_tokens == 0:
        raise RuntimeError("No tokens were extracted; refusing to return contract text")

    if stats.tokens_with_style_metadata == 0:
        raise RuntimeError(
            "No token style metadata was returned. Verify that this is an "
            "Enterprise Document OCR processor/version supporting "
            "premium_features.compute_style_info."
        )

    if stats.struck_tokens == 0 and not args.allow_no_strikeout:
        raise RuntimeError(
            "No struck-out tokens were detected. Because this workflow expects "
            "redlines, extraction is failing closed. Inspect the PDF and processor "
            "version, or pass --allow-no-strikeout for a confirmed clean document."
        )

    args.output_text.parent.mkdir(parents=True, exist_ok=True)
    args.output_text.write_text(extracted_text, encoding="utf-8")

    audit_path = args.output_text.with_suffix(args.output_text.suffix + ".audit.json")
    audit_path.write_text(
        json.dumps(
            {
                "recommended_api": "Google Cloud Document AI Enterprise Document OCR",
                "processor_id": processor_id,
                "processor_version": processor_version or "processor default",
                "input_file": args.input_pdf.name,
                **asdict(stats),
            },
            indent=2,
        )
        + "\n",
        encoding="utf-8",
    )

    print(json.dumps(asdict(stats)), file=sys.stderr)
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
