"""
Pick: ABBYY Cloud OCR SDK with FineReader XML output.

FineReader XML preserves strikeout formatting in runs that can split within a
word or number, allowing deleted characters to be excluded before text is sent
to the contract-question-answering agent.

Install:
    pip install requests

Environment:
    ABBYY_APP_ID=...
    ABBYY_APP_PASSWORD=...
    ABBYY_ENDPOINT=https://cloud.ocrsdk.com   # use your contracted region

Usage:
    python ocr_contract.py contract.pdf --output-dir ./results

Only the generated *.kept.txt file should be sent to the AI agent.
The *.audit.json file contains deleted text and must remain outside its context.
"""

from __future__ import annotations

import argparse
import hashlib
import io
import json
import os
import re
import sys
import time
import zipfile
from dataclasses import dataclass
from pathlib import Path
from typing import Optional
from xml.etree import ElementTree as ET

import requests


TERMINAL_FAILURES = {
    "processingfailed",
    "notenoughcredits",
    "deleted",
}


def local_name(name: str) -> str:
    return name.rsplit("}", 1)[-1]


def attr(element: ET.Element, name: str) -> Optional[str]:
    for key, value in element.attrib.items():
        if local_name(key) == name:
            return value
    return None


def bool_value(value: Optional[str], default: bool = False) -> bool:
    if value is None:
        return default
    return value.strip().lower() in {"1", "true", "yes"}


def task_from_response(xml_bytes: bytes) -> dict[str, str]:
    root = ET.fromstring(xml_bytes)
    for element in root.iter():
        if local_name(element.tag) == "task":
            return dict(element.attrib)
    raise RuntimeError(f"ABBYY response did not contain a task: {xml_bytes[:500]!r}")


class AbbyyCloudOCR:
    def __init__(
        self,
        app_id: str,
        app_password: str,
        endpoint: str = "https://cloud.ocrsdk.com",
    ) -> None:
        self.endpoint = endpoint.rstrip("/")
        self.session = requests.Session()
        self.session.auth = (app_id, app_password)
        self.session.headers["User-Agent"] = "contract-ocr/1.0"

    def submit(self, pdf_path: Path) -> str:
        # documentConversion is used because formatting—not just plain text—is
        # essential for recognizing strikeout runs.
        params = {
            "language": "English",
            "profile": "documentConversion",
            "exportFormat": "xml",
            "imageSource": "scanner",
            "textType": "normal",
            "correctOrientation": "true",
            "correctSkew": "true",
        }

        with pdf_path.open("rb") as pdf:
            response = self.session.post(
                f"{self.endpoint}/processDocument",
                params=params,
                files={"file": (pdf_path.name, pdf, "application/pdf")},
                timeout=(30, 180),
            )

        response.raise_for_status()
        task = task_from_response(response.content)

        task_id = task.get("id")
        if not task_id:
            raise RuntimeError(f"ABBYY did not return a task ID: {task}")

        return task_id

    def wait_for_result(
        self,
        task_id: str,
        timeout_seconds: int = 3600,
        poll_seconds: float = 5.0,
    ) -> str:
        deadline = time.monotonic() + timeout_seconds

        while time.monotonic() < deadline:
            response = self.session.get(
                f"{self.endpoint}/getTaskStatus",
                params={"taskId": task_id},
                timeout=(15, 60),
            )
            response.raise_for_status()
            task = task_from_response(response.content)

            status = task.get("status", "").lower()

            if status == "completed":
                result_url = task.get("resultUrl")
                if not result_url:
                    raise RuntimeError("ABBYY completed the task without a result URL")
                return result_url

            if status in TERMINAL_FAILURES:
                error = task.get("error", "No error detail returned")
                raise RuntimeError(f"ABBYY task {task_id} failed: {status}: {error}")

            time.sleep(poll_seconds)

        raise TimeoutError(f"ABBYY task {task_id} exceeded {timeout_seconds} seconds")

    def download_result(self, result_url: str) -> bytes:
        response = self.session.get(result_url, timeout=(30, 300))
        response.raise_for_status()
        content = response.content

        # Some configurations package the XML result in a ZIP file.
        if content.startswith(b"PK\x03\x04"):
            with zipfile.ZipFile(io.BytesIO(content)) as archive:
                xml_files = [
                    name for name in archive.namelist()
                    if name.lower().endswith(".xml")
                ]
                if not xml_files:
                    raise RuntimeError("ABBYY result ZIP contained no XML file")
                return archive.read(xml_files[0])

        return content

    def recognize(self, pdf_path: Path) -> tuple[str, bytes]:
        task_id = self.submit(pdf_path)
        result_url = self.wait_for_result(task_id)
        return task_id, self.download_result(result_url)


@dataclass
class OCRCharacter:
    value: str
    deleted: bool
    confidence: Optional[float]
    bbox: Optional[tuple[int, int, int, int]]


@dataclass
class OCRLine:
    raw: str
    kept: str
    characters: list[OCRCharacter]


def parse_number(value: Optional[str]) -> Optional[float]:
    if value is None:
        return None
    try:
        return float(value)
    except ValueError:
        return None


def character_bbox(element: ET.Element) -> Optional[tuple[int, int, int, int]]:
    try:
        return (
            int(float(attr(element, "l") or "")),
            int(float(attr(element, "t") or "")),
            int(float(attr(element, "r") or "")),
            int(float(attr(element, "b") or "")),
        )
    except ValueError:
        return None


def normalize_kept_line(text: str) -> str:
    text = text.replace("\u00a0", " ")
    text = re.sub(r"[ \t]+", " ", text).strip()
    text = re.sub(r" +([,.;:!?%)\]}])", r"\1", text)
    return text


def parse_line(line: ET.Element) -> OCRLine:
    characters: list[OCRCharacter] = []

    def walk(element: ET.Element, inherited_strikeout: bool = False) -> None:
        strikeout_attribute = attr(element, "strikeout")
        deleted = (
            bool_value(strikeout_attribute)
            if strikeout_attribute is not None
            else inherited_strikeout
        )

        if local_name(element.tag) == "charParams":
            text = element.text or ""
            confidence = parse_number(attr(element, "charConfidence"))
            bbox = character_bbox(element)

            for character in text:
                characters.append(
                    OCRCharacter(
                        value=character,
                        deleted=deleted,
                        confidence=confidence,
                        bbox=bbox,
                    )
                )
            return

        for child in element:
            walk(child, deleted)

    walk(line)

    raw = "".join(character.value for character in characters)
    kept = normalize_kept_line(
        "".join(
            character.value
            for character in characters
            if not character.deleted
        )
    )
    return OCRLine(raw=raw, kept=kept, characters=characters)


def union_bbox(
    characters: list[OCRCharacter],
) -> Optional[list[int]]:
    boxes = [character.bbox for character in characters if character.bbox]
    if not boxes:
        return None

    return [
        min(box[0] for box in boxes),
        min(box[1] for box in boxes),
        max(box[2] for box in boxes),
        max(box[3] for box in boxes),
    ]


def deleted_runs(
    line: OCRLine,
    page_number: int,
    line_number: int,
) -> list[dict]:
    runs: list[dict] = []
    current: list[OCRCharacter] = []

    def flush() -> None:
        if not current:
            return

        text = "".join(character.value for character in current).strip()
        if text:
            confidences = [
                character.confidence
                for character in current
                if character.confidence is not None
            ]
            runs.append(
                {
                    "page": page_number,
                    "line": line_number,
                    "deleted_text": text,
                    "bbox": union_bbox(current),
                    "minimum_character_confidence": (
                        min(confidences) if confidences else None
                    ),
                    "raw_line": line.raw,
                    "kept_line": line.kept,
                }
            )
        current.clear()

    for character in line.characters:
        if character.deleted:
            current.append(character)
        else:
            flush()
    flush()

    return runs


def contains_subtoken_edit(line: OCRLine) -> bool:
    chars = line.characters
    for left, right in zip(chars, chars[1:]):
        if (
            left.deleted != right.deleted
            and left.value.isalnum()
            and right.value.isalnum()
        ):
            return True
    return False


def descendants(element: ET.Element, tag: str) -> list[ET.Element]:
    return [
        child
        for child in element.iter()
        if child is not element and local_name(child.tag) == tag
    ]


def render_paragraph(
    paragraph: ET.Element,
    parsed_lines: dict[int, OCRLine],
) -> str:
    parts = [
        parsed_lines[id(line)].kept
        for line in descendants(paragraph, "line")
        if parsed_lines[id(line)].kept
    ]
    return normalize_kept_line(" ".join(parts))


def render_table(
    block: ET.Element,
    parsed_lines: dict[int, OCRLine],
) -> list[str]:
    output: list[str] = []
    rows = descendants(block, "row")

    for row in rows:
        cells = [
            child
            for child in row
            if local_name(child.tag) == "cell"
        ]

        rendered_cells = []
        for cell in cells:
            cell_lines = [
                parsed_lines[id(line)].kept
                for line in descendants(cell, "line")
                if parsed_lines[id(line)].kept
            ]
            rendered_cells.append(normalize_kept_line(" ".join(cell_lines)))

        if rendered_cells:
            output.append("\t".join(rendered_cells))

    return output


def render_block(
    block: ET.Element,
    parsed_lines: dict[int, OCRLine],
) -> list[str]:
    block_type = (attr(block, "blockType") or "").lower()

    if block_type == "table":
        table = render_table(block, parsed_lines)
        if table:
            return table

    paragraphs = descendants(block, "par")
    if paragraphs:
        return [
            text
            for paragraph in paragraphs
            if (text := render_paragraph(paragraph, parsed_lines))
        ]

    return [
        parsed_lines[id(line)].kept
        for line in descendants(block, "line")
        if parsed_lines[id(line)].kept
    ]


def extract_kept_text(
    xml_bytes: bytes,
    confidence_threshold: float = 65.0,
) -> tuple[str, dict]:
    root = ET.fromstring(xml_bytes)
    pages = [
        element for element in root.iter()
        if local_name(element.tag) == "page"
    ]

    rendered_pages: list[str] = []
    all_deleted_runs: list[dict] = []
    subtoken_edits: list[dict] = []
    review_reasons: list[str] = []

    for page_number, page in enumerate(pages, start=1):
        line_elements = descendants(page, "line")
        parsed_lines = {
            id(line): parse_line(line)
            for line in line_elements
        }

        for line_number, line_element in enumerate(line_elements, start=1):
            parsed = parsed_lines[id(line_element)]
            all_deleted_runs.extend(
                deleted_runs(parsed, page_number, line_number)
            )

            if contains_subtoken_edit(parsed):
                subtoken_edits.append(
                    {
                        "page": page_number,
                        "line": line_number,
                        "raw_line": parsed.raw,
                        "kept_line": parsed.kept,
                    }
                )

            # Low-confidence kept characters adjacent to a deletion are routed
            # for review because these are often replacement digits or letters.
            chars = parsed.characters
            for index, character in enumerate(chars):
                if character.deleted or not character.value.isalnum():
                    continue

                adjacent_to_deletion = any(
                    0 <= neighbor < len(chars) and chars[neighbor].deleted
                    for neighbor in (index - 1, index + 1)
                )
                low_confidence = (
                    character.confidence is None
                    or character.confidence < confidence_threshold
                )

                if adjacent_to_deletion and low_confidence:
                    review_reasons.append(
                        f"Page {page_number}, line {line_number}: "
                        "low-confidence kept character adjacent to deleted text"
                    )
                    break

        blocks = [
            child for child in page
            if local_name(child.tag) == "block"
        ]

        page_parts: list[str] = [f"[Page {page_number}]"]
        for block in blocks:
            rendered = render_block(block, parsed_lines)
            if rendered:
                page_parts.append("\n".join(rendered))

        # Fallback for an XML variant without direct page/block children.
        if len(page_parts) == 1:
            page_parts.extend(
                parsed_lines[id(line)].kept
                for line in line_elements
                if parsed_lines[id(line)].kept
            )

        rendered_pages.append("\n\n".join(page_parts))

    if not pages:
        review_reasons.append("ABBYY output contained no recognized pages")

    audit = {
        "provider": "ABBYY Cloud OCR SDK",
        "format": "FineReader XML",
        "page_count": len(pages),
        "deleted_run_count": len(all_deleted_runs),
        "deleted_runs": all_deleted_runs,
        "subtoken_edits": subtoken_edits,
        "review_required": bool(review_reasons),
        "review_reasons": sorted(set(review_reasons)),
    }

    return "\n\n".join(rendered_pages).strip() + "\n", audit


def sha256_file(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as file:
        for chunk in iter(lambda: file.read(1024 * 1024), b""):
            digest.update(chunk)
    return digest.hexdigest()


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("pdf", type=Path)
    parser.add_argument("--output-dir", type=Path, default=Path("."))
    parser.add_argument("--confidence-threshold", type=float, default=65.0)
    args = parser.parse_args()

    app_id = os.environ.get("ABBYY_APP_ID")
    app_password = os.environ.get("ABBYY_APP_PASSWORD")
    endpoint = os.environ.get(
